def _align_hands(hands, live):
    hands = list(hands or [])
    if len(hands) > live:
        return hands[:live]
    if len(hands) < live:
        return hands + [["PASS"] for _ in range(live - len(hands))]
    return hands

def agent(obs, config=None):
    step = int(obs.get("step", 0) or 0)
    player = int(obs.get("player", 0) or 0)
    farms = obs.get("farms", []) or []
    live = len(farms[player].get("hands", []) or []) if 0 <= player < len(farms) else 0
    entry = _TAPE[step] if 0 <= step < len(_TAPE) else {}
    entry = entry or {}
    return {
        "farmer": list(entry.get("farmer") or ["PASS"]),
        "hands": _align_hands(entry.get("hands"), live),
        "market": list(entry.get("market") or []),
    }

cropdusta_97601003_agent = agent
